<?php
/**
 * Sorting state for the database table breakdown.
 *
 * Sort links are generated by this plugin and carry a nonce; the requested
 * sort is only honoured when that nonce verifies. A request without a valid
 * nonce (a bookmark, a hand-edited URL) falls back to the default order.
 *
 * @package PivotPerformanceToolkit
 */

declare(strict_types=1);

namespace PivotPerformanceToolkit\Admin;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

final class TableSort {

	private const NONCE_ACTION = 'pivot_performance_toolkit_table_sort';

	private const COLUMNS = array( 'name', 'engine', 'rows', 'size' );

	private const DEFAULT_COLUMN    = 'size';
	private const DEFAULT_DIRECTION = 'desc';

	/**
	 * @return array{sort_by: string, sort_dir: string}
	 */
	public static function fromRequest(): array {
		$sort = array(
			'sort_by'  => self::DEFAULT_COLUMN,
			'sort_dir' => self::DEFAULT_DIRECTION,
		);

		$nonce = isset( $_GET['_wpnonce'] ) ? sanitize_text_field( wp_unslash( (string) $_GET['_wpnonce'] ) ) : '';

		if ( '' === $nonce || ! current_user_can( 'manage_options' ) || ! wp_verify_nonce( $nonce, self::NONCE_ACTION ) ) {
			return $sort;
		}

		$column    = isset( $_GET['sort'] ) ? sanitize_key( wp_unslash( (string) $_GET['sort'] ) ) : '';
		$direction = isset( $_GET['sort_dir'] ) ? sanitize_key( wp_unslash( (string) $_GET['sort_dir'] ) ) : '';

		if ( in_array( $column, self::COLUMNS, true ) ) {
			$sort['sort_by'] = $column;
		}

		if ( in_array( $direction, array( 'asc', 'desc' ), true ) ) {
			$sort['sort_dir'] = $direction;
		}

		return $sort;
	}

	/**
	 * Link that toggles the size column's direction, preserving the screen it is shown on.
	 */
	public static function nextSizeUrl( string $base_url, string $sort_by, string $sort_dir ): string {
		$next_dir = ( 'size' === $sort_by && 'asc' === $sort_dir ) ? 'desc' : 'asc';

		return add_query_arg(
			array(
				'sort'     => 'size',
				'sort_dir' => $next_dir,
				'_wpnonce' => wp_create_nonce( self::NONCE_ACTION ),
			),
			$base_url
		);
	}
}
